import { useId, type ChangeEvent, type FormEvent } from "react";
import "./CommandBox.css";

export interface CommandReply {
  text: string;
  isError: boolean;
}

export interface CommandBoxProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (value: string) => void;
  reply?: CommandReply;
}

const PLACEHOLDER = "Type a command, then press Enter";

export function CommandBox({ value, onChange, onSubmit, reply }: CommandBoxProps) {
  const inputId = useId();
  const replyId = useId();

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    onChange(event.target.value);
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit(value);
  }

  const replyClassName = reply?.isError
    ? "command-box__reply command-box__reply--error"
    : "command-box__reply";

  return (
    <form className="command-box" onSubmit={handleSubmit}>
      <label className="command-box__label" htmlFor={inputId}>
        Command
      </label>

      <div className="command-box__row">
        <input
          id={inputId}
          className="command-box__input"
          type="text"
          value={value}
          onChange={handleChange}
          placeholder={PLACEHOLDER}
          autoComplete="off"
          spellCheck={false}
          aria-describedby={reply ? replyId : undefined}
        />
        <button className="command-box__button" type="submit">
          Run
        </button>
      </div>

      {reply && (
        <div
          id={replyId}
          className={replyClassName}
          role={reply.isError ? "alert" : "status"}
        >
          {reply.isError && <span className="command-box__tag">Error</span>}
          <span>{reply.text}</span>
        </div>
      )}
    </form>
  );
}
```

