  color: var(--ink);
}

.command-box__label {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.command-box__row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.command-box__input {
  flex: 1 1 auto;
  min-width: 0;
  font: inherit;
  font-size: clamp(1rem, 0.6rem + 1vw, 1.25rem);
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--muted);
  border-radius: 999px;
  padding: 0.6em 1.1em;
  transition: border-color 150ms ease;
}

.command-box__input::placeholder {
  color: var(--muted);
}

.command-box__input:focus {
  border-color: var(--cresyl);
}

.command-box__button {
  flex: 0 0 auto;
  font: inherit;
  font-size: clamp(0.9rem, 0.5rem + 0.8vw, 1.05rem);
  color: var(--slide);
  background: var(--myelin);
  border: 1px solid var(--myelin);
  border-radius: 999px;
  padding: 0.6em 1.2em;
  cursor: pointer;
  transition: border-color 150ms ease;
}

.command-box__button:hover {
  border-color: var(--ink);
}

.command-box__reply {
  font-size: clamp(0.875rem, 0.4rem + 0.7vw, 1rem);
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  background: var(--code-bg);
  border-left: 3px solid var(--myelin);
  border-radius: 0.5rem;
  padding: 0.5em 0.9em;
}

.command-box__reply--error {
  background: var(--cresyl-wash);
  border-left-color: var(--cresyl);
}

.command-box__tag {
  margin-right: 0.5em;
  font-weight: 600;
  color: var(--cresyl);
}

:root[data-motion="reduce"] .command-box__input,
:root[data-motion="reduce"] .command-box__button,
@media (prefers-reduced-motion: reduce) {
  .command-box__input,
  .command-box__button {
    transition: none;
  }
}
